const item=$input.item.json;
const topic=item['Topic']||'';
const sourceUrl=item['Source URL']||item['Source_URL']||'';
const client=(item['Client']&&typeof item['Client']==='object')?(item['Client'].name||''):(item['Client']||'AlfredAI');
const existingNotes=item['Static_Notes']||'';
const rawPick=item['Static Skill Picker'];
const skillOverride=(typeof rawPick==='string'?rawPick:(rawPick&&rawPick.name)||'').trim();
const STAGE_TAG='STATIC (skill)';
const sep='==============================';
// remove any prior block for THIS stage so it self-replaces; keep everything else
const blockRe=new RegExp('\\n*'+sep+'\\n'+STAGE_TAG.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'[\\s\\S]*?(?=(\\n'+sep+'\\n)|$)','g');
const notesBase=existingNotes.replace(blockRe,'').trim();
return{json:{record_id:item.id||'',topic,source_url:sourceUrl,client,notes_base:notesBase,stage_tag:STAGE_TAG,sep,has_link:!!(sourceUrl&&sourceUrl.trim().length>5),skill_override:skillOverride}};

const MANUS_PROJECT_ID='3c8Tpmj5hWFRdgFS8UHb45';
const d=$input.item.json;
const folderUrl=d.drive_folder_url||'';
const folderId=d.sub_folder_id||'';
const fileName=(d.subfolder_name||'conceptual')+'_final.png';
const msg='Recreate this LinkedIn post for AlfredAI as a conceptual branded graphic, following your full end-to-end workflow (extract the source post, write original AlfredAI brand-voice copy, generate the conceptual graphic with the brand design system, and composite the logo).

IMPORTANT: Generate the conceptual graphic image using Nano Banana Pro (the built-in image generation tool). Use Nano Banana Pro for all image generation in this task.

LOGO (mandatory - use the OFFICIAL AlfredAI logo): Composite the official AlfredAI logo asset bundled in your skill (use your composite logo script / logo template). Do NOT generate, redraw, recreate, or approximate the logo with an image model. Do NOT put any black box, dark rectangle, colored panel, or solid shape behind it - it is a transparent wordmark and the graphic must show through around the letters. If it appears low-contrast, the only allowed enhancement is a soft feathered glow, never a filled box.

Source LinkedIn post:
'+d.source_url+'

PRE-SHIP QUALITY CHECK (mandatory - do this BEFORE uploading anything to Google Drive): Before you upload, review the final graphic and the post copy and verify ALL of the following. Do NOT upload until every item passes; if any fails, fix it and re-render first.
1. TEXT CORRECTNESS: all on-graphic text and the post copy are accurate, spelled correctly, grammatically clean, and match the intended message. No placeholder text, no cut-off words.
2. NO OVERLAP: no text overlaps other text, graphics, the logo, or edges. Everything sits inside safe margins. Nothing is clipped or running off-canvas.
3. READABILITY: every text element is legible against its background with strong contrast; headline is the dominant element; nothing too small or crowded.
4. GRAPHICS CORRECT: the graphic, colors, and logo are correct, on-brand, not distorted, not duplicated, and relevant to the message. The AlfredAI logo is the official asset, transparent, with no box behind it.
5. COMPLETENESS: the final PNG and the post copy are both present.
Only once every check passes, proceed to upload.

UPLOAD (MANDATORY - required final step, do not skip it):
DESTINATION_FOLDER_ID: '+folderId+'
DESTINATION_FOLDER_URL: '+folderUrl+'
OUTPUT_FILENAME: '+fileName+'

Export the final graphic as a PNG named '+fileName+'. After the quality check passes, upload it to the user's Google Drive using rclone, targeting the EXISTING destination folder by its ID with the flag --drive-root-folder-id '+folderId+' so the PNG lands directly INSIDE that existing folder. The destination is a shared drive, so include shared-drive support. Run the upload EXACTLY ONCE; do not re-run or duplicate. Do NOT create a new folder. Do NOT use the folder ID as a new folder name. Do NOT leave the file only in your task workspace. After uploading, confirm in your task output the exact file you placed in that folder, and provide the post copy.';
return{json:{...d,manus_message:msg,output_filename:fileName,manus_project_id:MANUS_PROJECT_ID}};

const resp=$input.item.json||{};
const ctx=$('6. Build Manus Message').item.json;
const project=ctx.manus_project_id||'(none)';
const rec=ctx.record_id||'(no id)';
if(resp.ok===false||!Array.isArray(resp.data)){throw new Error('skill.list failed for Manus project '+project+' on record '+rec+': '+JSON.stringify(resp).substring(0,300)+'. Nothing submitted.');}
const all=resp.data.filter(Boolean);
const norm=s=>String(s||'').trim().toLowerCase();
const DEFAULT_SKILL='alfredai-conceptual-linkedin-post-creator';
const override=String(ctx.skill_override||'').trim();
const wanted=override||DEFAULT_SKILL;
const source=override?'record override':'default';
const projectSkills=all.filter(s=>s.owner_type==='project');
const matches=projectSkills.filter(s=>norm(s.name)===norm(wanted));
if(matches.length!==1||!matches[0].id){
  const nonProject=all.filter(s=>s.owner_type!=='project'&&norm(s.name)===norm(wanted)).map(s=>(s.owner_type||'unknown')+' '+s.id);
  let why;
  if(matches.length>1)why=matches.length+' project skills share this name ('+matches.map(s=>s.id).join(', ')+')';
  else if(nonProject.length)why='only non-project copies exist ['+nonProject.join(', ')+']; personal, team, official and app skills are not allowed';
  else why='no project skill with this name';
  throw new Error('Skill '+wanted+' ('+source+') not resolved for record '+rec+' in Manus project '+project+': '+why+'. Project skills available: '+(projectSkills.map(s=>s.name).join(', ')||'(none)')+'. Nothing submitted.');
}
const hit=matches[0];
return{json:{...ctx,resolved_skill_id:hit.id,resolved_skill_name:hit.name||wanted,resolved_skill_owner_type:hit.owner_type,resolved_skill_source:source,skill_resolve_error:''}};

